<section class="panel"><h2>Supplier directory</h2><div class="table-wrap"><table><tr><th>Supplier</th><th>Contact</th><th>Phone</th><th>Email</th><th>Address</th><?php if(manager()) echo '<th>Actions</th>'; ?></tr><?php $rows=query('SELECT * FROM suppliers ORDER BY name')->fetchAll(); foreach($rows as $r): ?><tr><?php foreach(['name','contact_person','phone','email','address'] as $key): ?><td><?= e($r[$key]) ?></td><?php endforeach; if(manager()): ?><td class="actions"><a href="?page=suppliers&edit=<?= $r['id'] ?>">Edit</a><?php deleteForm('delete_supplier',$r['id']); ?></td><?php endif ?></tr><?php endforeach ?></table></div><?php if(!$rows) echo '<p class="empty">No suppliers yet.</p>'; ?></section>
<?php if(manager()): $r=query('SELECT * FROM suppliers WHERE id=?',[(int)($_GET['edit']??0)])->fetch()?:[]; ?><section class="panel"><h2><?= $r?'Edit supplier':'Add supplier' ?></h2><?php startForm('save_supplier',$r['id']??0); ?><div class="form-grid"><?php foreach(['name'=>'Supplier name','contact_person'=>'Contact person','phone'=>'Contact number','email'=>'Email','address'=>'Address'] as $key=>$label) field($key,$label,$r[$key]??'',$key==='email'?'email':'text',$key==='name'); ?></div><?php endForm(); ?></section><?php endif ?>
